import {categories,vehicleTypes,services,money,priceFor,quote,supportsService} from './catalog.js';
import {icon,art} from './art.js';
import {garageSummary} from './vehicle-data.js';
import {parts,productById,productMatches,defaultOptions,priceLine,quoteCommerce,configurationKey,vehicleSignature} from './commerce.js';
import {configurator,mountConfigurator,readConfiguration,marketplacePage,partCards,filteredParts,commerceCart,commerceBill,partRequestForm,requestHistory,commerceTracking,deliveryNames} from './shop-ui.js';
import {vehicleForm as renderVehicleForm,mountVehicleForm,readVehicleIdentity,garagePage as renderGaragePage,savedVehicleAccount,vehicleRecordModal,challanModal,documentPayload} from './vehicle-ui.js';
import {adBanner,mountAds,starMechanics,mechanicModal,subscriptionSection,subscriptionsPage,subscriptionForm,mountSubscriptionForm,readSubscription,subscriptionHistory,subscriptionCancelModal} from './care-ui.js';

const $=selector=>document.querySelector(selector);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('pitstop:'+key))??fallback;}catch{return fallback;}};
const ui={page:'home',category:'all',search:'',sort:'popular',cart:load('cart',[]),favorites:load('favorites',[]),vehicleId:load('vehicle',null),addressId:load('address',null),coupon:load('coupon',''),modal:null,onlyFavorites:false,busy:false,checkoutDraft:null,partCategory:'all',partOrigin:'all',partSort:'recommended'};
let db,toastTimer,focusBeforeModal;
const persist=()=>{try{for(const [key,value] of Object.entries({cart:ui.cart,favorites:ui.favorites,vehicle:ui.vehicleId,address:ui.addressId,coupon:ui.coupon}))localStorage.setItem('pitstop:'+key,JSON.stringify(value));}catch{}};
async function api(path,method='GET',body){const response=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},...(body!==undefined?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Something went wrong. Please try again.');return data;}
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').className='visible';toastTimer=setTimeout(()=>$('#toast').className='',3400);}
const vehicle=()=>db.vehicles.find(v=>v.id===ui.vehicleId)||db.vehicles[0];
const address=()=>db.addresses.find(a=>a.id===ui.addressId)||db.addresses[0];
const count=()=>ui.cart.reduce((sum,item)=>sum+item.quantity,0);
const vehicleName=v=>v?`${v.brand} ${v.model}`:'your vehicle';
const statusNames={confirmed:'Booking confirmed',assigned:'Mechanic assigned',enroute:'On the way',arrived:'Mechanic arrived',in_progress:'Service in progress',completed:'Service completed',cancelled:'Booking cancelled'};
const dateTime=value=>new Date(value).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit',timeZone:'Asia/Kolkata'});
function currentQuote(){try{return quoteCommerce(ui.cart,db.vehicles,ui.coupon,{preview:true});}catch(error){if(ui.coupon){const fallback=quoteCommerce(ui.cart,db.vehicles,'',{preview:true});ui.coupon='';persist();notify('Offer removed: eligible labour no longer meets its conditions.');return fallback;}throw error;}}
function serviceEstimate(service){const v=vehicle();if(!v)return priceFor(service,'scooter');try{return priceLine({kind:'service',id:service.id,quantity:1,options:defaultOptions({kind:'service',id:service.id},v)},v,{preview:true}).unitPrice;}catch{return priceFor(service,v.type);}}
function refreshMarketplace(){const grid=$('#parts-grid');if(grid)grid.innerHTML=partCards(ui,vehicle());const label=$('#part-count');if(label)label.textContent=filteredParts(ui,vehicle()).length+' reference / demo listings · Search by name, brand or part number above';}
function bindMarketplace(){for(const [id,key]of [['#part-sort','partSort'],['#part-origin','partOrigin']])$(id)?.addEventListener('change',event=>{ui[key]=event.target.value;refreshMarketplace();});}
function button(text,action,cls='primary',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function render(){
 const v=vehicle(),a=address();ui.vehicleId=v?.id||null;ui.addressId=a?.id||null;
 $('#app').innerHTML=`
 <a class="skip-link" href="#main">Skip to services</a>
 <header class="header"><div class="header-inner">
  <button class="wordmark" data-action="nav" data-page="home" aria-label="Pitstop home">pitstop<span>✦</span></button>
  <span class="header-divider"></span>
  <button class="location" data-action="addresses"><span class="location-icon">${icon('pin')}</span><span><span class="eyebrow">SERVICE AT YOUR DOORSTEP</span><strong>${escape(a?.area||'Choose your address')} ${icon('down')}</strong><small>${escape(a?.city||'India')} ${a?'· '+escape(a.pin):''}</small></span></button>
  <label class="global-search">${icon('search')}<input type="search" id="search" placeholder="${ui.page==='parts'?'Search parts, brands or OEM part numbers':'Try puncture repair or bike service'}" aria-label="${ui.page==='parts'?'Search parts':'Search services'}" value="${escape(ui.search)}"><kbd>⌕</kbd></label>
  <button class="account-button" data-action="account" aria-label="Account">${icon('user')}<span>${escape(db.profile.name?.split(' ')[0]||'Account')}</span></button>
  <button class="cart-button" data-action="cart">${icon('bag')}<span>My cart</span><b id="cart-count">${count()}</b></button>
 </div></header>
 <nav class="main-nav" aria-label="Main navigation"><div class="nav-inner"><div class="nav-links">${[['home','Home'],['services','All services'],['parts','Parts & accessories'],['subscriptions','Daily care'],['offers','Offers'],['garage','My garage'],['orders','My orders']].map(([id,name])=>`<button data-action="nav" data-page="${id}" class="${ui.page===id?'active':''}">${name}${id==='offers'?'<i class="nav-dot"></i>':''}</button>`).join('')}</div><button class="nav-help" data-action="nav" data-page="help">${icon('help')} Need a hand?</button><span class="demo-label"><i></i> Local demo</span></div></nav>
 <main id="main" class="main">${pageContent()}</main>
 <footer><div class="footer-inner"><div><button class="wordmark" data-action="nav" data-page="home">pitstop<span>✦</span></button><p>A little care. A better ride.</p></div><div><strong>Built for Indian roads.</strong><p>Scooters. Motorcycles. Cars. And everything in between.</p></div><div class="footer-links"><button data-action="nav" data-page="help">Help & FAQs</button><button data-action="policy">Service terms</button><small>Local demo · No real dispatch or payments</small></div></div><div class="footer-bottom">© ${new Date().getFullYear()} Pitstop. Your everyday pit crew.<span>Made with care, for every mile.</span></div></footer>
 <nav class="mobile-nav" aria-label="Mobile navigation">${[['home','home','Home'],['services','grid','Services'],['parts','bag','Parts'],['garage','scooter','Garage'],['orders','orders','Orders']].map(([page,i,label])=>`<button data-action="nav" data-page="${page}" class="${ui.page===page?'active':''}">${icon(i)}<span>${label}</span></button>`).join('')}<button data-action="cart">${icon('bag')}<span>Cart${count()?' · '+count():''}</span></button></nav>`;
 bindSearch();bindMarketplace();mountAds();persist();$('#app').inert=!!ui.modal;
}
function pageContent(){
 if(ui.page==='subscriptions')return subscriptionsPage(db.subscriptions,db.vehicles,vehicle()?.id);
 if(ui.page==='parts')return marketplacePage(ui,db.vehicles,vehicle(),vehicleBar());if(ui.page==='garage')return garagePage();if(ui.page==='orders')return ordersPage();if(ui.page==='offers')return offersPage();if(ui.page==='help')return helpPage();
 return `${ui.page==='home'?hero():`<div class="page-heading"><span class="eyebrow">A HEALTHIER RIDE STARTS HERE</span><h1>Every service. One pitstop.</h1><p>Expert care for the everyday commute and the long way home.</p></div>`}${vehicleBar()}<section class="shop-home-strip"><span>${icon('bag')}</span><div><strong>Parts for your ride. Fitted, if you like.</strong><p>Shop parts & accessories · Delivery + 25% off installation labour</p></div><button class="text-button" data-action="nav" data-page="parts">Shop parts ${icon('arrow')}</button></section>${categorySection()}<section class="catalog-section" id="catalog"><div class="section-heading"><div><span class="eyebrow">${ui.page==='home'?'THE EVERYDAY ESSENTIALS':'FIND YOUR NEXT FIX'}</span><h2 id="catalog-heading">${ui.category==='all'?'Popular services near you':categories.find(c=>c.id===ui.category)?.name}</h2><p id="result-count">Picked for your ${escape(vehicleName(vehicle()))}. Priced with care.</p></div><div class="catalog-controls"><button class="filter-button ${ui.onlyFavorites?'selected':''}" data-action="favorites" aria-pressed="${ui.onlyFavorites}">${icon('heart')} Saved</button><label class="sort-wrap">${icon('filter')}<select id="sort" aria-label="Sort services"><option value="popular" ${ui.sort==='popular'?'selected':''}>Recommended</option><option value="low" ${ui.sort==='low'?'selected':''}>Price: low to high</option><option value="high" ${ui.sort==='high'?'selected':''}>Price: high to low</option><option value="rating" ${ui.sort==='rating'?'selected':''}>Top rated</option></select></label></div></div><div class="services-grid" id="service-grid">${serviceCards()}</div></section>${subscriptionSection()}${ui.page==='home'?`<section class="promise"><div class="promise-intro"><span class="eyebrow">THE PITSTOP PROMISE</span><h2>Good hands. <br>Great peace of mind.</h2></div>${[['shield','People you can trust','Skilled professionals, thoughtful service.'],['wallet','No surprise bills','Approve any extra work before it begins.'],['home','Your place. Your pace.','Doorstep care that fits your day.']].map(([i,title,copy])=>`<div class="promise-item"><span>${icon(i)}</span><h3>${title}</h3><p>${copy}</p></div>`).join('')}</section><section class="care-banner"><div class="care-icon">${icon('leaf')}</div><div><h3>Love your ride. It’ll love you back.</h3><p>A regular check-up today can save a breakdown tomorrow.</p></div>${button('Find my next service '+icon('arrow'),'periodic','text-button')}</section><div class="catalog-note">${icon('info')} Illustrative starting prices for ${escape(vehicle()?.type||'scooter')} services. Selected parts, fluids and fuel are included in configured estimates. Ratings are sample data.</div>${starMechanics()}`:''}`;
}
function hero(){return adBanner();}
function vehicleBar(){const v=vehicle(),stats=garageSummary(v?[v]:[]),due=stats.due.length+stats.expired.length;return `<div class="vehicle-bar"><span class="vehicle-bar-icon">${icon(v?.type==='car'?'car':'scooter')}</span><div><small>PERSONALISED FOR YOUR RIDE</small><strong>${escape(vehicleName(v))} <span>${escape(vehicleTypes.find(t=>t.id===v?.type)?.name||'Choose a vehicle')}${v?.year?' · '+v.year:''}</span></strong></div><button data-action="vehicles">${v?'Change vehicle':'Add your vehicle'} ${icon('chevron')}</button>${v?`<button class="vehicle-bar-end vehicle-record-link ${due?'has-renewals':''}" data-action="vehicle-record" data-id="${v.id}">${icon(due?'clock':'shield')} ${due?due+' renewal'+(due===1?'':'s')+' to review':'Vehicle documents & challans'}</button>`:''}</div>`;}
function categorySection(){return `<section class="category-section"><div class="section-heading compact"><h2>A fix for every little thing.</h2><button type="button" class="daily-care-shortcut" data-action="nav" data-page="subscriptions">Daily care plans ${icon('arrow')}</button></div><div class="categories" role="group" aria-label="Service categories">${categories.map((cat,index)=>`<button data-action="category" data-id="${cat.id}" class="category ${ui.category===cat.id?'active':''}" aria-pressed="${ui.category===cat.id}"><span class="category-art tone-${index}">${icon(cat.icon)}</span><span>${cat.name}</span></button>`).join('')}</div></section>`;}
function filteredServices(){let list=services.filter(s=>supportsService(s,vehicle()||{type:'scooter'}));if(ui.category!=='all')list=list.filter(s=>s.category===ui.category);if(ui.onlyFavorites)list=list.filter(s=>ui.favorites.includes(s.id));const words=ui.search.toLowerCase().replace(/\bbike\b/g,'motorcycle').split(/\s+/).filter(Boolean);if(words.length)list=list.filter(s=>{const hay=`${s.name} ${s.subtitle} ${s.includes.join(' ')} ${categories.find(c=>c.id===s.category)?.name} ${s.vehicles.join(' ')} ${s.vehicles.includes('bike')?'motorcycle':''} ${s.vehicles.includes('scooter')?'scooty':''} ${s.vehicles.includes('superbike')?'superbike':''}`.toLowerCase();return words.every(word=>hay.includes(word));});if(ui.sort==='low')list.sort((a,b)=>a.price-b.price);if(ui.sort==='high')list.sort((a,b)=>b.price-a.price);if(ui.sort==='rating')list.sort((a,b)=>Number(b.rating)-Number(a.rating));return list;}
function serviceCards(){const list=filteredServices();if(!list.length)return `<div class="empty-state wide">${icon('search')}<h3>No fixes found here.</h3><p>Try a different search, vehicle or category.</p>${button('Clear filters','clear-filters','primary')}</div>`;return list.map(s=>{return `<article class="service-card"><div class="product-image bg-${s.category}"><button class="art-button" data-action="service" data-id="${s.id}" aria-label="View ${escape(s.name)}">${art(s.art)}</button>${s.badge?`<span class="product-badge">${s.badge}</span>`:''}<button class="favorite ${ui.favorites.includes(s.id)?'saved':''}" data-action="favorite" data-id="${s.id}" aria-label="${ui.favorites.includes(s.id)?'Unsave':'Save'} ${escape(s.name)}" aria-pressed="${ui.favorites.includes(s.id)}">${icon('heart')}</button><span class="time-tag">${icon('clock')} ${s.time}</span></div><div class="product-body"><div class="rating">${icon('star')} <strong>${s.rating}</strong><span>(${s.reviews})</span><span class="doorstep">${s.id==='alignment'?'Workshop':'Doorstep'}</span></div><button class="service-title" data-action="service" data-id="${s.id}">${s.name}</button><p>${s.subtitle}</p><div class="product-bottom"><div class="price"><strong>${money(serviceEstimate(s))}</strong><small>From · configured estimate</small></div>${button('ADD '+icon('plus'),'add','add-button',`data-id="${s.id}"`)}</div></div></article>`;}).join('');}
function refreshCatalog(){const grid=$('#service-grid');if(grid)grid.innerHTML=serviceCards();const heading=$('#catalog-heading');if(heading)heading.textContent=ui.search?`Results for “${ui.search}”`:ui.onlyFavorites?'Your saved services':ui.category==='all'?'Popular services near you':categories.find(c=>c.id===ui.category)?.name;const result=$('#result-count');if(result)result.textContent=(ui.search||ui.onlyFavorites)?`${filteredServices().length} services for your ${vehicleName(vehicle())}`:`Picked for your ${vehicleName(vehicle())}. Priced with care.`;}
function bindSearch(){const search=$('#search');search?.addEventListener('input',()=>{ui.search=search.value;if(ui.page==='parts'){refreshMarketplace();$('#parts-grid')?.scrollIntoView({block:'start'});return;}if(!['home','services'].includes(ui.page)){ui.page='services';render();$('#search').focus();$('#search').setSelectionRange(ui.search.length,ui.search.length);}refreshCatalog();if(ui.search)$('#catalog')?.scrollIntoView({block:'start'});});$('#sort')?.addEventListener('change',e=>{ui.sort=e.target.value;refreshCatalog();});}
function updateCart(){persist();const badge=$('#cart-count');if(badge)badge.textContent=count();if(ui.page==='parts')refreshMarketplace();else refreshCatalog();if(ui.modal?.type==='cart')renderModal();const mobile=$('.mobile-nav [data-action="cart"] span');if(mobile)mobile.textContent='Cart'+(count()?' · '+count():'');}
function add(id){openModal('configure',{item:{kind:'service',id}});}
function remove(key){ui.cart=ui.cart.filter(i=>i.key!==key);updateCart();}
function navigate(page){ui.page=page;if(location.hash!=='#'+page)history.pushState({},'', '#'+page);ui.search='';ui.category='all';ui.onlyFavorites=false;render();window.scrollTo({top:0,behavior:'smooth'});}
function openModal(type,data={}){if(ui.modal?.type==='checkout'&&$('#checkout-form'))ui.checkoutDraft=Object.fromEntries(new FormData($('#checkout-form')));if(!ui.modal)focusBeforeModal=document.activeElement;ui.modal={type,data};renderModal();}
function closeModal(){ui.modal=null;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');$('#app').inert=false;focusBeforeModal?.focus?.();}
function modalHeading(title,subtitle=''){return `<div class="modal-heading"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;}
function renderModal(){
 if(!ui.modal)return;const {type,data}=ui.modal;const drawer=['cart','checkout','tracking','vehicle-record'].includes(type);
 let html='';if(type==='subscription')html=subscriptionForm(db.vehicles,db.addresses,db.profile,data.vehicleId||vehicle()?.id);if(type==='subscription-cancel')html=subscriptionCancelModal(data.id);if(type==='mechanic')html=mechanicModal(data.id);if(type==='configure')html=configurator(data.item,db.vehicles,vehicle()?.id);if(type==='part-request')html=partRequestForm(db.vehicles,data.vehicleId||vehicle()?.id);
 if(type==='vehicle-record')html=vehicleRecordModal(db.vehicles.find(v=>v.id===data.id),data.view||'overview');if(type==='challan-form')html=challanModal(db.vehicles.find(v=>v.id===data.id),db.vehicles.find(v=>v.id===data.id)?.challans?.find(c=>c.id===data.challanId));
 if(type==='vehicle-delete')html=`${modalHeading('Remove this saved vehicle?','Its saved documents and manual challan records will also be removed.')}<div class="modal-content"><p>Existing service bookings keep their original vehicle details.</p><div class="button-row">${button('Keep vehicle','close','secondary')}${button('Remove vehicle','confirm-delete-vehicle','danger',`data-id="${escape(data.id)}"`)}</div></div>`;
 if(type==='challan-delete')html=`${modalHeading('Remove this challan record?','This removes only the record saved in Pitstop.')}<div class="modal-content"><p>This does not cancel or pay the actual challan.</p><div class="button-row">${button('Keep record','record-tab','secondary',`data-id="${escape(data.id)}" data-view="challans"`)}${button('Remove record','confirm-delete-challan','danger',`data-id="${escape(data.id)}" data-challan="${escape(data.challanId)}"`)}</div></div>`;
 if(type==='cart')html=cartModal();if(type==='checkout')html=checkoutModal();if(type==='service')html=serviceModal(data.id);if(type==='addresses')html=addressesModal();if(type==='address-add')html=addressForm(data);if(type==='vehicles')html=vehiclesModal();if(type==='vehicle-add')html=vehicleForm();if(type==='account')html=accountModal();if(type==='tracking')html=trackingModal(data.id);if(type==='policy')html=policyModal();if(type==='change-vehicle')html=`${modalHeading('Switch your ride?','Your cart has services priced for your current vehicle.')}<div class="modal-content"><p>Switching vehicles clears the cart so we can show compatible services and the right prices.</p><div class="button-row">${button('Keep current vehicle','vehicles','secondary')}${button('Switch & clear cart','confirm-vehicle','primary',`data-id="${escape(data.id)}"`)}</div></div>`;if(type==='cancel-order')html=`${modalHeading('Cancel this booking?','You can book again whenever you need us.')}<div class="modal-content"><p>No payment has been collected for this demo booking.</p><div class="button-row">${button('Keep booking','track','secondary',`data-id="${escape(data.id)}"`)}${button('Cancel booking','confirm-cancel','danger',`data-id="${escape(data.id)}"`)}</div></div>`;
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${drawer?'drawer':''} ${type==='service'?'service-modal':''} ${type==='vehicle-record'?'vehicle-record-drawer':''} ${type==='configure'?'configuration-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1">${html}<div class="form-error" id="form-error" role="alert"></div></section></div>`;document.body.classList.add('modal-open');
 setTimeout(()=>{$('.modal')?.focus();},0);
 $('#checkout-date')?.addEventListener('change',updateSlots);
 $('#app').inert=true;if(type==='configure'&&$('#configuration-form'))mountConfigurator($('#configuration-form'),data.item,db.vehicles);
 if(type==='subscription'&&$('#subscription-form'))mountSubscriptionForm($('#subscription-form'),db.vehicles);
 if(type==='checkout'&&ui.checkoutDraft){const form=$('#checkout-form'),draft=ui.checkoutDraft;for(const name of ['name','phone','notes','date']){if(draft[name]!==undefined&&form.elements[name])form.elements[name].value=draft[name];}for(const name of ['timing','payment']){const input=[...form.querySelectorAll('input')].find(i=>i.name===name&&i.value===draft[name]);if(input)input.checked=true;}if(draft.timing==='scheduled'){$('#schedule-fields').classList.remove('hidden');updateSlots();if(draft.slot)$('#checkout-slot').value=draft.slot;}if(draft.consent)form.elements.consent.checked=true;}
 if(type==='address-add'&&data.id){const saved=db.addresses.find(a=>a.id===data.id);if(saved){for(const name of ['label','line','area','city','pin','landmark'])$('#address-form').elements[name].value=saved[name]||'';$('#modal-title').textContent='Edit your address';$('#address-form button[type=submit]').textContent='Save address changes';}}
 if(type==='vehicle-add')mountVehicleForm($('#vehicle-form'),db.vehicles.find(v=>v.id===data.id));
 if(type==='challan-form'){const form=$('#challan-form');form.elements.reference.required=true;form.elements.issuedOn.required=true;form.elements.issuedOn.max=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});}
}
function serviceModal(id){const s=services.find(x=>x.id===id);return `${modalHeading(s.name,s.subtitle)}<div class="detail-art bg-${s.category}">${art(s.art)}</div><div class="modal-content"><div class="detail-meta"><span>${icon('star')} ${s.rating} · ${s.reviews} sample reviews</span><span>${icon('clock')} ${s.time}</span></div><h3>A little care, with a lot included.</h3><ul class="included">${s.includes.map(i=>`<li>${icon('check')}${i}</li>`).join('')}</ul><div class="info-box">${icon('info')}<p>${s.note}</p></div><div class="detail-footer"><div><small>For your ${escape(vehicleName(vehicle()))}</small><strong>${money(serviceEstimate(s))}<span> starting price</span></strong></div>${button('Choose options '+icon('plus'),'add','primary',`data-id="${id}"`)}</div></div>`;}
function bill(t){if(t.pricingVersion===2)return commerceBill(t);return `<div class="bill"><h3>Price breakdown</h3><div><span>Service subtotal</span><span>${money(t.subtotal)}</span></div>${t.discount?`<div class="green"><span>FIRSTFIX savings</span><span>−${money(t.discount)}</span></div>`:''}<div><span>Visit & convenience fee</span><span>${t.visitFee?money(t.visitFee):'<span class="green">FREE</span>'}</span></div><div class="bill-total"><strong>Total estimate</strong><strong>${money(t.total)}</strong></div><small>Illustrative demo rates. Parts, fluids and fuel are extra. Any applicable taxes are included in shown service fees.</small></div>`;}
function cartModal(){try{if(count())currentQuote();}catch{}return commerceCart(ui.cart,db.vehicles,ui.coupon);}
function checkoutModal(){if(!count())return cartModal();const t=currentQuote();const now=new Date();const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);const max=new Date(now.getTime()+7*86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});return `${modalHeading('The last little details','Your next smoother ride starts here.')}<form id="checkout-form" class="drawer-form"><div class="drawer-body"><div class="checkout-items-note">${count()} configured item(s) · ${new Set(ui.cart.map(i=>i.vehicleId)).size} vehicle(s). Selected parts, fuel and labour are itemised below.</div><div class="checkout-step"><span>1</span><h3>${t.fulfillment==='delivery'?'Where should we deliver?':'Where should we come?'}</h3></div>${db.addresses.length?`<label class="field">Service address<select name="addressId" required>${db.addresses.map(a=>`<option value="${a.id}" ${a.id===address()?.id?'selected':''}>${escape(a.label)} — ${escape(a.line)}, ${escape(a.city)} ${escape(a.pin)}</option>`).join('')}</select></label>`:'<p>No address saved yet. Add one to continue.</p>'}<button type="button" class="text-button small" data-action="address-add" data-return="checkout">${icon('plus')} Add a new address</button><div class="checkout-step"><span>2</span><h3>When works for you?</h3></div><div class="radio-cards"><label><input type="radio" name="timing" value="asap" checked><span><strong>As soon as possible</strong><small>Demo arrival estimate: ${t.fulfillment==='delivery'?'30–45 min':'45–90 min'}</small></span>${icon('bolt')}</label><label><input type="radio" name="timing" value="scheduled"><span><strong>Schedule for later</strong><small>Choose a day and time · IST</small></span>${icon('clock')}</label></div><div id="schedule-fields" class="two-fields hidden"><label class="field">Date<input type="date" id="checkout-date" name="date" min="${today}" max="${max}" value="${today}"></label><label class="field">Arrival slot<select name="slot" id="checkout-slot" aria-label="Arrival slot">${slots(today)}</select></label></div><div class="checkout-step"><span>3</span><h3>Let’s stay connected</h3></div><div class="two-fields"><label class="field">Your name<input name="name" autocomplete="name" required minlength="2" maxlength="60" value="${escape(db.profile.name)}" placeholder="Full name"></label><label class="field">Mobile number<div class="phone-input"><span>+91</span><input name="phone" aria-label="Mobile number" type="tel" inputmode="numeric" autocomplete="tel-national" pattern="[6-9][0-9]{9}" maxlength="10" required value="${escape(db.profile.phone)}" placeholder="98765 43210"></div></label></div><label class="field">Anything we should know? <span class="optional">Optional</span><textarea name="notes" maxlength="500" placeholder="Parking instructions, symptoms, or a little extra detail…" rows="2"></textarea></label><div class="checkout-step"><span>4</span><h3>${t.fulfillment==='delivery'?'Pay on delivery':'Pay after your service'}</h3></div><div class="radio-cards"><label><input type="radio" name="payment" value="${t.fulfillment==='delivery'?'UPI on delivery':'UPI after service'}" checked><span><strong>${t.fulfillment==='delivery'?'UPI on delivery':'UPI after service'}</strong><small>No payment collected in this demo</small></span>${icon('wallet')}</label><label><input type="radio" name="payment" value="${t.fulfillment==='delivery'?'Cash on delivery':'Cash after service'}"><span><strong>${t.fulfillment==='delivery'?'Cash on delivery':'Cash after service'}</strong><small>Pay the agreed final amount after fulfilment</small></span>${icon('wallet')}</label></div>${bill(t)}<label class="consent"><input type="checkbox" name="consent" required><span>I agree to the <button type="button" class="inline-link" data-action="checkout-terms">service terms</button> and understand this is a demo booking with no real dispatch.</span></label><div class="inline-terms hidden" id="checkout-terms">Illustrative service fees cover only listed inclusions. Selected parts, fuel and labour are included in the estimate. Unselected work requires a separate quote and approval. Arrival estimates are simulated. No payment is collected and no mechanic is dispatched. You may cancel before the mechanic-arrived stage in this demo.</div></div><div class="drawer-footer"><button type="button" class="back-button" data-action="cart">${icon('chevron')} Cart</button><button type="submit" class="primary">Place demo order · ${money(t.total)} ${icon('arrow')}</button></div></form>`;}
function slots(date){let result='';for(let hour=8;hour<=18;hour+=2){const iso=`${date}T${String(hour).padStart(2,'0')}:00:00+05:30`;if(new Date(iso).getTime()>Date.now()+30*60000)result+=`<option value="${hour}">${hour>12?hour-12:hour}:00 ${hour>=12?'PM':'AM'} – ${hour+2>12?hour+2-12:hour+2}:00 ${hour+2>=12?'PM':'AM'}</option>`;}return result||'<option value="">No slots left. Choose another date.</option>';}
function updateSlots(){$('#checkout-slot').innerHTML=slots($('#checkout-date').value);}
function addressesModal(){return `${modalHeading('Where’s your pitstop?','Choose where your ride needs a little care.')}<div class="modal-content"><div class="address-list">${db.addresses.map(a=>`<div class="selectable ${a.id===address()?.id?'selected':''}"><button class="selection-main" data-action="select-address" data-id="${a.id}"><span class="selection-icon">${icon(a.label==='Work'?'car':'home')}</span><span><strong>${escape(a.label)}${a.id===address()?.id?'<b class="tiny-badge">SELECTED</b>':''}</strong><p>${escape(a.line)}, ${escape(a.area)}</p><small>${escape(a.city)} · ${escape(a.pin)}${a.landmark?' · '+escape(a.landmark):''}</small></span></button><button class="icon-button delete-button" data-action="edit-address" data-id="${a.id}" aria-label="Edit ${escape(a.label)} address">${icon('tool')}</button><button class="icon-button delete-button" data-action="delete-address" data-id="${a.id}" aria-label="Delete ${escape(a.label)} address">${icon('trash')}</button></div>`).join('')||'<p>No saved addresses. Let’s add your first.</p>'}</div>${button(icon('plus')+' Add a new address','address-add','secondary full')}<div class="info-box">${icon('pin')}<p>Demo cities: Bengaluru, Mumbai, Delhi, Hyderabad, Chennai and Pune. PIN codes are format-checked; live coverage isn’t connected.</p></div></div>`;}
function addressForm(data){return `${modalHeading('A new place to pitstop','Tell us exactly where to find you.')}<form id="address-form" class="modal-content"><label class="field">Save as<select name="label"><option>Home</option><option>Work</option><option>Other</option></select></label><label class="field">Flat / house, building & street<input name="line" required minlength="5" maxlength="180" autocomplete="street-address" placeholder="e.g. 12, Sunshine Apartments, 3rd Cross"></label><label class="field">Locality / area<input name="area" required minlength="2" maxlength="80" placeholder="e.g. Indiranagar"></label><div class="two-fields"><label class="field">City<select name="city">${db.cities.map(city=>`<option ${city===address()?.city?'selected':''}>${city}</option>`).join('')}</select></label><label class="field">PIN code<input name="pin" required pattern="[1-9][0-9]{5}" inputmode="numeric" maxlength="6" placeholder="560038" autocomplete="postal-code"></label></div><label class="field">Landmark <span class="optional">Optional</span><input name="landmark" maxlength="120" placeholder="Near the park, opposite the bakery…"></label><button type="submit" class="primary full">Save address ${icon('check')}</button></form>`;}
function vehiclesModal(){return `${modalHeading('Your garage','The right care starts with the right ride.')}<div class="modal-content"><div class="address-list">${db.vehicles.map(v=>`<div class="selectable ${v.id===vehicle()?.id?'selected':''}"><button class="selection-main" data-action="select-vehicle" data-id="${v.id}"><span class="selection-icon">${icon(v.type==='car'?'car':'scooter')}</span><span><strong>${escape(vehicleName(v))}${v.id===vehicle()?.id?'<b class="tiny-badge">SELECTED</b>':''}</strong><p>${escape(vehicleTypes.find(t=>t.id===v.type)?.name)} ${v.number?'· '+escape(v.number):''}</p></span></button></div>`).join('')||'<p>Add your vehicle to see compatible services.</p>'}</div>${button(icon('plus')+' Add a vehicle','vehicle-add','secondary full')}<p class="muted small-note">Service prices and availability adapt to your vehicle type.</p></div>`;}
function vehicleForm(){return renderVehicleForm(db.vehicles.find(v=>v.id===ui.modal.data.id));}
function accountModal(){return `${modalHeading('A familiar face. A better pitstop.','Your details are saved only on this computer.')}<form id="profile-form" class="modal-content"><div class="profile-avatar">${icon('user')}</div>${savedVehicleAccount(db.vehicles)}<label class="field">Your name<input name="name" required minlength="2" maxlength="60" autocomplete="name" value="${escape(db.profile.name)}" placeholder="Full name"></label><label class="field">Indian mobile number<div class="phone-input"><span>+91</span><input name="phone" aria-label="Mobile number" type="tel" inputmode="numeric" required pattern="[6-9][0-9]{9}" maxlength="10" autocomplete="tel-national" value="${escape(db.profile.phone)}" placeholder="9876543210"></div></label><div class="info-box">${icon('shield')}<p>This is a local demo profile. No SMS is sent. Phone verification and sign-in aren’t connected.</p></div><button type="submit" class="primary full">Save my details ${icon('check')}</button><div class="account-shortcuts">${button(icon('pin')+' Saved addresses','addresses','text-button')}${button(icon('scooter')+' My garage','vehicles','text-button')}${button(icon('offer')+' Offers','nav','text-button','data-page="offers"')}</div></form>`;}
function garagePage(){return renderGaragePage(db.vehicles,vehicle()?.id);}
function ordersPage(){return legacyOrdersPage()+subscriptionHistory(db.subscriptions)+requestHistory(db.partRequests);}
function legacyOrdersPage(){return `<div class="page-heading"><span class="eyebrow">EVERY FIX, ALL IN ONE PLACE</span><h1>Your orders.</h1><p>Services, parts deliveries and installation, all in one place.</p></div>${!db.orders.length?`<div class="empty-state page-empty">${icon('orders')}<h2>Your first pitstop is waiting.</h2><p>Book a little care for your ride and follow it here.</p>${button('Explore services','shop','primary')}</div>`:`<div class="orders-list">${db.orders.map(o=>`<article class="order-card"><div class="order-top"><span class="status ${o.status}"><i></i>${deliveryNames(o)[o.status]}</span><small>${escape(o.id)} · ${dateTime(o.createdAt)} IST</small></div><div class="order-main"><div class="order-icon">${icon(o.vehicle.type==='car'?'car':'scooter')}</div><div><h3>${o.totals.lines.map(l=>escape(l.name)).join(' + ')}</h3><p>${o.vehicles?.length>1?o.vehicles.length+' vehicles':escape(vehicleName(o.vehicle))} · ${escape(o.address.label)}, ${escape(o.address.area)}</p><small>${o.schedule==='asap'?'As soon as possible':dateTime(o.schedule)+' IST'} · ${escape(o.payment)}</small></div><strong>${money(o.totals.total)}</strong></div><div class="order-bottom"><span>${o.rating?'★'.repeat(o.rating)+' · Thanks for the love!':o.status==='completed'?'A little care. A better ride.':o.status==='cancelled'?'No payment collected.':'Demo order · No real delivery or dispatch'}</span>${button(['completed','cancelled'].includes(o.status)?'View details':'Track booking '+icon('arrow'),'track','secondary',`data-id="${o.id}"`)}</div></article>`).join('')}</div>`}`;}
function trackingModal(id){const o=db.orders.find(o=>o.id===id);if(!o)return modalHeading('Booking not found');if(o.totals.pricingVersion===2)return commerceTracking(o);const stages=['confirmed','assigned','enroute','arrived','in_progress','completed'];const stage=stages.indexOf(o.status);return `${modalHeading(o.status==='confirmed'?'You’re booked in!':statusNames[o.status],escape(o.id)+' · Demo booking')}<div class="drawer-body"><div class="tracking-map"><div class="map-road road-one"></div><div class="map-road road-two"></div><div class="map-road road-three"></div><div class="map-park park-one"></div><div class="map-park park-two"></div><div class="map-route"></div><span class="map-marker mechanic-marker">${icon('tool')}</span><span class="map-marker home-marker">${icon('home')}</span><span class="map-label">${escape(o.address.area)}</span><span class="map-caption">Illustrated map · No live location</span></div><div class="tracking-summary"><span class="status ${o.status}"><i></i>${statusNames[o.status]}</span><h3>${o.status==='cancelled'?'Until your next pitstop.':o.status==='completed'?'Here’s to a smoother ride.':o.schedule==='asap'?'A little help is on the horizon.':'A little care, right on time.'}</h3><p>${o.schedule==='asap'?'Demo arrival estimate: 30–60 min after assignment':dateTime(o.schedule)+' IST · Scheduled arrival'}</p></div>${o.status!=='cancelled'?`<ol class="timeline">${stages.map((s,i)=>`<li class="${i<=stage?'done':''} ${i===stage?'current':''}"><span>${i<=stage?icon('check'):''}</span><div><strong>${statusNames[s]}</strong>${o.history.find(h=>h.status===s)?`<small>${dateTime(o.history.find(h=>h.status===s).at)} IST</small>`:''}${s==='assigned'&&stage>=1?'<small>Arjun · Demo mechanic · Sample rating 4.9</small>':''}</div></li>`).join('')}</ol>`:''}<div class="booking-details"><h3>Your booking details</h3><p>${icon('scooter')} ${escape(vehicleName(o.vehicle))}</p><p>${icon('pin')} ${escape(o.address.line)}, ${escape(o.address.area)}, ${escape(o.address.city)} ${escape(o.address.pin)}</p><p>${icon('user')} ${escape(o.customer.name)} · +91 ${escape(o.customer.phone)}</p>${o.notes?`<p>${icon('info')} ${escape(o.notes)}</p>`:''}<div class="order-line-items">${o.totals.lines.map(l=>`<div><span>${escape(l.name)} × ${l.quantity}</span><strong>${money(l.unitPrice*l.quantity)}</strong></div>`).join('')}</div>${bill(o.totals)}<p class="payment-note">${icon('wallet')} ${escape(o.payment)} · No payment collected</p></div>${o.status==='completed'?`<form id="rating-form"><h3>How was your demo pitstop?</h3><div class="star-rating" aria-label="Rate your service">${[1,2,3,4,5].map(n=>`<button type="button" class="${o.rating>=n?'selected':''}" data-action="rate" data-id="${o.id}" data-rating="${n}" aria-label="Rate ${n} stars" aria-pressed="${o.rating===n}">${icon('star')}</button>`).join('')}</div></form>`:''}<div class="info-box">${icon('info')}<p>This is a simulated journey. Use “Next demo stage” to explore each step. No professional has been contacted.</p></div></div><div class="drawer-footer">${['confirmed','assigned','enroute'].includes(o.status)?button('Cancel booking','cancel-order','text-button',`data-id="${o.id}"`):'<span></span>'}${stage>=0&&stage<5?button('Next demo stage '+icon('arrow'),'advance','primary',`data-id="${o.id}"`):button('Browse services','cart-browse','primary')}</div>`;}
function offersPage(){const used=db.orders.some(o=>o.status!=='cancelled');return `<div class="page-heading"><span class="eyebrow">GOOD CARE. A LITTLE LESS.</span><h1>A little treat for your ride.</h1><p>Simple savings, with the details right up front.</p></div><div class="offers-grid"><article class="offer-card"><span class="offer-icon">${icon('offer')}</span><span class="eyebrow">YOUR FIRST PITSTOP</span><h2>15% off.<br>100% care.</h2><p>Save up to ₹150 on your first service booking.</p><div class="coupon-ticket"><strong>FIRSTFIX</strong>${button(used?'Already used':ui.coupon?'Applied '+icon('check'):'Use this offer','use-offer','secondary',used?'disabled':'')}</div><small>First non-cancelled booking only · Min. eligible labour ₹499 · Maximum discount ₹150 · Parts and fuel excluded.</small></article><article class="offer-card pale"><span class="offer-icon">${icon('home')}</span><span class="eyebrow">A LITTLE EXTRA, ON US</span><h2>More care.<br>Zero visit fee.</h2><p>Your ₹49 visit fee is on us when your service subtotal reaches ₹999.</p><button class="primary" data-action="shop">Explore services ${icon('arrow')}</button><small>Automatically applied to eligible carts. Based on the service subtotal before coupon discounts.</small></article></div>`;}
const faqs=[['How does Pitstop work?','Choose your vehicle, select services, add your address and pick a time. This local demo saves your booking and lets you explore a simulated mechanic journey. It does not dispatch a real mechanic.'],['Are parts, engine oil and fuel included?','Configured estimates include the parts, consumables, fuel quantities and labour you select. Additional work or unselected parts require a separate quote and approval. Review the itemised cart before booking.'],['Can I book for a superbike or an EV?','Yes. Add the correct vehicle type in My garage. Available services and prices adapt to your ride. High-voltage EV repairs and manufacturer-only diagnostics require an authorized service centre.'],['Which cities are covered?','The demo lets you save addresses in Bengaluru, Mumbai, Delhi, Hyderabad, Chennai and Pune. These are illustrative service areas. Real coverage and dispatch are not connected.'],['How do I pay?','Choose UPI after service or cash after service. No money is collected in this local demo. A production app would need verified payment and invoicing integrations.'],['Can I cancel a booking?','You can cancel a demo booking while it is confirmed, assigned or on the way. Open My bookings, choose Track booking and select Cancel booking.'],['Where is my information stored?','Profiles, vehicles, addresses and bookings are saved in a local JSON file on the computer running the server. Your cart and saved services are stored in your browser. This demo has one shared local profile.'],['What about fuel delivery?','Fuel entries demonstrate the booking flow only. The shown amount is a delivery fee, excluding fuel. Real fuel delivery must use authorized providers and confirm vehicle compatibility, local availability and operating requirements.']];
function helpPage(){return `<div class="page-heading"><span class="eyebrow">WE’VE GOT YOUR BACK</span><h1>A little help goes a long way.</h1><p>Everything you need to know before your next pitstop.</p></div><div class="help-layout"><div class="faqs">${faqs.map(([q,a])=>`<details><summary>${q}${icon('plus')}</summary><p>${a}</p></details>`).join('')}</div><aside class="help-aside"><span>${icon('help')}</span><h2>Your everyday<br>pit crew.</h2><p>Start with a vehicle health check if you’re unsure what your ride needs.</p>${button('Find a health check '+icon('arrow'),'diagnostic','primary')}<small>Support chat and calls are not connected in this demo.</small></aside></div>`;}
function policyModal(){return `${modalHeading('A few things, clearly explained.','Pitstop local demo · Service terms')}<div class="modal-content terms"><h3>Booking and dispatch</h3><p>This application is a local demonstration. Arrival times, mechanics, ratings and tracking are sample data. Creating a booking does not contact a service provider.</p><h3>Prices and scope</h3><p>All prices are illustrative estimates in Indian rupees. Parts, consumables, fuel, workshop charges and extra work are excluded unless specifically listed. Any real additional work should be quoted and approved before it starts. The shown demo service prices include any applicable taxes.</p><h3>Payments and cancellation</h3><p>No money is collected. The selected payment method is saved as a preference. Demo bookings can be cancelled before the mechanic-arrived stage. Real cancellation and payment terms would need to be agreed with the provider.</p><h3>Fuel and specialist services</h3><p>Fuel delivery is a demonstration only and requires authorized providers in a real launch. EV high-voltage repairs, specialized diagnostics and complex repairs need appropriately qualified technicians or authorized workshops.</p><h3>Local information</h3><p>There is one shared demo profile per server. Do not expose this local server publicly or enter sensitive personal information. To reset it, stop the server, remove the data folder and clear this site’s browser storage.</p></div>`;}

document.addEventListener('click',async event=>{
 const backdrop=event.target.closest('.modal-backdrop');if(backdrop&&event.target===backdrop){closeModal();return;}
 const el=event.target.closest('[data-action]');if(!el||el.disabled||ui.busy)return;
 const action=el.dataset.action,id=el.dataset.id;
 try{
  if(action==='ad-explore'){
   if(id==='0'){const v=vehicle();if(v&&supportsService(services.find(s=>s.id==='oil-change'),v))openModal('configure',{item:{kind:'service',id:'oil-change'}});else{openModal('vehicles');notify('Choose a petrol or diesel vehicle for an engine oil change.');}}
   if(id==='1'){if(vehicle()?.type==='scooter')openModal('configure',{item:{kind:'service',id:'basic-service'}});else{openModal('vehicles');notify('Choose or add your scooter to explore its care.');}}
   if(id==='2'){if(vehicle())openModal('vehicle-record',{id:vehicle().id,view:'documents'});else openModal('vehicle-add');}
  }
  if(action==='mechanic')openModal('mechanic',{id});
  if(action==='mechanic-service'){closeModal();if(vehicle()&&supportsService(services.find(s=>s.id===id),vehicle()))openModal('configure',{item:{kind:'service',id}});else openModal('vehicles');}
  if(action==='subscribe')openModal('subscription',{vehicleId:id||vehicle()?.id});
  if(action==='subscription-cancel')openModal('subscription-cancel',{id});
  if(action==='subscription-state'){ui.busy=true;await api(`subscriptions/${id}/status`,'PUT',{status:el.dataset.state});db=await api('state');closeModal();render();notify(el.dataset.state==='cancelled'?'Daily care plan cancelled. No payment collected.':el.dataset.state==='paused'?'Plan paused. End date stays the same.':'Daily care plan resumed');}
  if(action==='nav'){closeModal();navigate(el.dataset.page);}
  if(action==='shop'||action==='cart-browse'){closeModal();navigate('services');}
  if(action==='browse')$('#catalog').scrollIntoView({behavior:'smooth',block:'start'});
  if(action==='periodic'||action==='rescue'){ui.category=action==='rescue'?'rescue':'periodic';ui.search='';ui.onlyFavorites=false;if(!['home','services'].includes(ui.page))ui.page='services';render();$('#catalog').scrollIntoView({behavior:'smooth',block:'start'});}
  if(action==='category'){ui.category=id;ui.search='';ui.onlyFavorites=false;render();if(id!=='all')$('#catalog').scrollIntoView({behavior:'smooth',block:'start'});}
  if(action==='clear-filters'){ui.category='all';ui.search='';ui.onlyFavorites=false;render();$('#catalog').scrollIntoView({behavior:'smooth'});}
  if(action==='favorites'){ui.onlyFavorites=!ui.onlyFavorites;render();refreshCatalog();$('#catalog').scrollIntoView({behavior:'smooth'});}
  if(action==='favorite'){ui.favorites=ui.favorites.includes(id)?ui.favorites.filter(x=>x!==id):[...ui.favorites,id];persist();refreshCatalog();}
  if(action==='part-config')openModal('configure',{item:{kind:'part',id}});
  if(action==='part-category'){ui.partCategory=id;render();$('#parts-grid')?.scrollIntoView({block:'start'});}
  if(action==='part-request')openModal('part-request',{vehicleId:el.dataset.vehicle||vehicle()?.id});
  if(action==='edit-cart'){const item=ui.cart.find(i=>i.key===el.dataset.key);if(item)openModal('configure',{item:{...item,options:{...item.options}}});}
  if(action==='cart-delete')remove(el.dataset.key);
  if(action==='cart-increase'||action==='cart-decrease'){const item=ui.cart.find(i=>i.key===el.dataset.key);if(item){const next=item.quantity+(action==='cart-increase'?1:-1);if(next<1)remove(item.key);else{priceLine({...item,quantity:next},db.vehicles.find(v=>v.id===item.vehicleId),{preview:true});item.quantity=next;updateCart();}}}
  if(action==='add')add(id);if(action==='remove')remove(id);
  if(['cart','vehicles','addresses','account','policy','vehicle-add'].includes(action))openModal(action);
  if(action==='service')openModal('service',{id});
  if(action==='diagnostic'){const s=services.find(s=>s.id==='diagnostic');openModal('service',{id:s.id});}
  if(action==='edit-address')openModal('address-add',{id,returnTo:'addresses'});
  if(action==='vehicle-record'||action==='record-tab')openModal('vehicle-record',{id,view:el.dataset.view||'overview'});
  if(action==='challan-add'||action==='challan-edit')openModal('challan-form',{id,challanId:el.dataset.challan});
  if(action==='challan-remove')openModal('challan-delete',{id,challanId:el.dataset.challan});
  if(action==='confirm-delete-challan'){ui.busy=true;await api('vehicles/'+id+'/challans/'+el.dataset.challan,'DELETE',{});db=await api('state');render();openModal('vehicle-record',{id,view:'challans'});notify('Local challan record removed');}
  if(action==='challan-paid'){ui.busy=true;const record=db.vehicles.find(v=>v.id===id)?.challans?.find(c=>c.id===el.dataset.challan);if(!record)throw new Error('Challan record not found.');await api('vehicles/'+id+'/challans/'+record.id,'PUT',{...record,status:'paid'});db=await api('state');render();openModal('vehicle-record',{id,view:'challans'});notify('Record marked paid. No payment was made by Pitstop.');}
  if(action==='edit-vehicle'){if(ui.cart.some(i=>i.vehicleId===id)){notify('Clear your cart before editing the selected vehicle.');return;}openModal('vehicle-add',{id});}
  if(action==='address-add')openModal('address-add',{returnTo:el.dataset.return||'addresses'});
  if(action==='close')closeModal();
  if(action==='select-address'){ui.addressId=id;persist();render();closeModal();notify('Service address updated');}
  if(action==='delete-address'){await api('addresses/'+id,'DELETE',{});db=await api('state');if(ui.addressId===id)ui.addressId=db.addresses[0]?.id;render();renderModal();notify('Address removed');}
  if(action==='delete-vehicle'){if(ui.cart.some(i=>i.vehicleId===id)){notify('Clear your cart before removing the selected vehicle.');return;}openModal('vehicle-delete',{id});}
  if(action==='confirm-delete-vehicle'){ui.busy=true;await api('vehicles/'+id,'DELETE',{});db=await api('state');if(ui.vehicleId===id)ui.vehicleId=db.vehicles[0]?.id;closeModal();render();notify('Saved vehicle removed');}
  if(action==='select-vehicle'||action==='garage-select'){ui.vehicleId=id;ui.category='all';persist();render();closeModal();notify('Your ride is selected');}
  if(action==='confirm-vehicle'){ui.cart=[];ui.coupon='';ui.checkoutDraft=null;ui.vehicleId=id;ui.category='all';persist();render();closeModal();notify('Vehicle switched. Explore care for your ride.');}
  if(action==='checkout'){if(!count())return;if(ui.cart.some(i=>i.needsConfiguration))throw new Error('Review your earlier cart items before checkout.');quoteCommerce(ui.cart,db.vehicles,ui.coupon);openModal('checkout');}
  if(action==='remove-coupon'){ui.coupon='';persist();renderModal();}
  if(action==='use-offer'){ui.coupon='FIRSTFIX';persist();navigate('services');notify('FIRSTFIX saved. Add ₹499 in services to use it.');}
  if(action==='track')openModal('tracking',{id});
  if(action==='advance'){ui.busy=true;await api(`orders/${id}/advance`,'POST',{});db=await api('state');render();renderModal();}
  if(action==='cancel-order')openModal('cancel-order',{id});
  if(action==='confirm-cancel'){ui.busy=true;await api(`orders/${id}/cancel`,'POST',{});db=await api('state');render();openModal('tracking',{id});notify('Booking cancelled. No payment was collected.');}
  if(action==='rate'){ui.busy=true;await api(`orders/${id}/rate`,'POST',{rating:Number(el.dataset.rating)});db=await api('state');render();renderModal();notify('Thanks for the love!');}
  if(action==='checkout-terms')$('#checkout-terms').classList.toggle('hidden');
 }catch(error){showError(error.message);}finally{ui.busy=false;}
});
document.addEventListener('change',event=>{if(event.target.name==='timing'){$('#schedule-fields')?.classList.toggle('hidden',event.target.value!=='scheduled');}});
function showError(message){const error=$('#form-error');if(error){error.textContent=message;error.classList.add('has-error');error.scrollIntoView({behavior:'smooth',block:'nearest'});}else notify(message);}
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['profile-form','address-form','vehicle-form','coupon-form','checkout-form','vehicle-documents-form','challan-form','configuration-form','part-request-form','subscription-form'].includes(form.id))return;event.preventDefault();if(ui.busy)return;const data=Object.fromEntries(new FormData(form));const submit=form.querySelector('[type="submit"]');ui.busy=true;submit.disabled=true;const original=submit.innerHTML;submit.textContent='One moment…';const error=$('#form-error');if(error){error.textContent='';error.classList.remove('has-error');}
 try{
  if(form.id==='subscription-form'){
   const input=readSubscription(form),selected=db.vehicles.find(v=>v.id===input.vehicleId);input.vehicleSignature=vehicleSignature(selected);
   await api('subscriptions','POST',input);db=await api('state');closeModal();navigate('subscriptions');document.querySelector('.subscription-history').scrollIntoView({behavior:'smooth',block:'start'});notify('Your daily care demo plan is saved. No payment collected.');
  }
  if(form.id==='configuration-form'){
   const item=readConfiguration(form,ui.modal.data.item),v=db.vehicles.find(v=>v.id===item.vehicleId);item.vehicleSignature=vehicleSignature(v);item.needsConfiguration=false;priceLine(item,v);
   const previousKey=item.key,remaining=ui.cart.filter(i=>i.key!==previousKey),match=remaining.find(i=>configurationKey(i)===configurationKey(item));
   if(match){if(['petrol','diesel'].includes(item.id))throw new Error('This fuel configuration is already in your cart. Edit its litres instead.');if(match.quantity+item.quantity>5)throw new Error('Maximum 5 identical configured items per order.');match.quantity+=item.quantity;match.vehicleSignature=item.vehicleSignature;match.options={...item.options};match.needsConfiguration=false;ui.cart=remaining;}else{if(remaining.length>=50)throw new Error('Maximum 50 configured lines per cart.');item.key=previousKey||'cart-'+crypto.randomUUID();ui.cart=[...remaining,item];}
   persist();updateCart();if(previousKey)openModal('cart');else closeModal();notify(previousKey?'Cart configuration updated':'Configured item added to your cart');
  }
  if(form.id==='part-request-form'){await api('part-requests','POST',data);db=await api('state');closeModal();navigate('orders');notify('Sourcing request saved locally. No supplier has been contacted.');}
  if(form.id==='profile-form'){db.profile=await api('profile','PUT',data);render();closeModal();notify('Your details are saved');}
  if(form.id==='address-form'){const returnTo=ui.modal.data.returnTo;const editId=ui.modal.data.id;const saved=await api('addresses'+(editId?'/'+editId:''),editId?'PUT':'POST',data);db=await api('state');ui.addressId=saved.id;render();openModal(returnTo==='checkout'?'checkout':'addresses');notify('Address saved');}
  if(form.id==='vehicle-form'){const editId=ui.modal.data.id;const saved=await api('vehicles'+(editId?'/'+editId:''),editId?'PUT':'POST',readVehicleIdentity(form));db=await api('state');if(!count())ui.vehicleId=saved.id;render();openModal('vehicle-record',{id:saved.id,view:'overview'});notify(editId?'Vehicle details updated':'Your vehicle is saved. Add documents whenever you’re ready.');}
  if(form.id==='vehicle-documents-form'){const id=ui.modal.data.id;await api('vehicles/'+id+'/documents','PUT',documentPayload(form));db=await api('state');render();openModal('vehicle-record',{id,view:'overview'});notify('Document details saved. Your expiry reminders are up to date.');}
  if(form.id==='challan-form'){const {id,challanId}=ui.modal.data;await api('vehicles/'+id+'/challans'+(challanId?'/'+challanId:''),challanId?'PUT':'POST',data);db=await api('state');render();openModal('vehicle-record',{id,view:'challans'});notify('Challan record saved');}
  if(form.id==='coupon-form'){if(db.orders.some(o=>o.status!=='cancelled')&&data.coupon.trim().toUpperCase()==='FIRSTFIX')throw new Error('FIRSTFIX is available on your first booking only.');quoteCommerce(ui.cart,db.vehicles,data.coupon,{preview:true});ui.coupon=data.coupon.trim().toUpperCase();persist();renderModal();notify(ui.coupon?'Offer applied. A little saving for your ride.':'Offer removed');}
  if(form.id==='checkout-form'){
   if(!data.addressId)throw new Error('Add a service address first.');
   let schedule='asap';if(data.timing==='scheduled'){if(!data.slot)throw new Error('Choose a date with an available slot.');schedule=new Date(`${data.date}T${String(data.slot).padStart(2,'0')}:00:00+05:30`).toISOString();}
   db.profile=await api('profile','PUT',{name:data.name,phone:data.phone});
   const order=await api('orders','POST',{vehicleId:ui.cart[0].vehicleId,addressId:data.addressId,items:ui.cart,coupon:ui.coupon,payment:data.payment,schedule,notes:data.notes});
   ui.cart=[];ui.coupon='';ui.checkoutDraft=null;ui.addressId=data.addressId;db=await api('state');ui.page='orders';history.pushState({},'','#orders');persist();render();openModal('tracking',{id:order.id});notify('Your demo pitstop is booked!');
  }
 }catch(error){showError(error.message);if(submit.isConnected){submit.disabled=false;submit.innerHTML=original;}}finally{ui.busy=false;}
});
document.addEventListener('keydown',event=>{if(!ui.modal)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const focusable=[...document.querySelectorAll('.modal button:not([disabled]), .modal input:not([disabled]), .modal select:not([disabled]), .modal textarea:not([disabled]), .modal a[href]')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(!first){event.preventDefault();return;}if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal'))){event.preventDefault();first.focus();}}});
window.addEventListener('popstate',()=>{const page=location.hash.slice(1)||'home';if(['home','services','parts','subscriptions','offers','garage','orders','help'].includes(page)){ui.page=page;ui.search='';ui.category='all';closeModal();render();window.scrollTo(0,0);}});
async function boot(){try{db=await api('state');const initialPage=location.hash.slice(1);if(['home','services','parts','subscriptions','offers','garage','orders','help'].includes(initialPage))ui.page=initialPage;if(!Array.isArray(ui.cart))ui.cart=[];ui.cart=ui.cart.filter(i=>i&&((i.kind==='part'&&productById(i.id))||services.some(s=>s.id===i.id))&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=5);if(!Array.isArray(ui.favorites))ui.favorites=[];const v=vehicle();ui.cart=ui.cart.map(i=>{if(!i.kind){const entry={...i,kind:'service',key:'cart-'+crypto.randomUUID(),vehicleId:v?.id,options:v?defaultOptions({kind:'service',id:i.id},v):{},needsConfiguration:true};return entry;}const saved=db.vehicles.find(v=>v.id===i.vehicleId);if(!saved||i.vehicleSignature!==vehicleSignature(saved))i.needsConfiguration=true;return i;});render();}catch(error){$('#app').innerHTML=`<div class="boot"><strong>pitstop<span>✦</span></strong><h2>We couldn’t get started.</h2><p>${escape(error.message)}</p><p>Start the local server and reload this page.</p><button class="primary" id="retry">Try again</button></div>`;$('#retry').addEventListener('click',boot);}}
boot();
